#include "before_exposed.cpp"
#include <chrono>
#include <fstream>
#include <iostream>
using Clock=std::chrono::steady_clock;
struct Query {std::uint64_t n,k;bool trivial;};
int main(int argc,char**argv){
 std::ifstream in(argv[1]);int t;std::uint32_t mod;in>>t>>mod;std::vector<Query>q; q.reserve(t);
 for(int i=0;i<t;++i){std::uint64_t n,k;in>>n>>k;q.push_back({n,std::min(k,n-k),k==0||k==n||k==1||k==n-1});}
 BinomialMod b(mod,mod-1);std::uint64_t check=0;auto start=Clock::now();for(auto x:q){asm volatile("" : "+g"(x.n),"+g"(x.k) : : "memory");check+=b.COM(x.n,x.k);}auto end=Clock::now();
 std::cout<<"full,0,"<<std::chrono::duration<double,std::nano>(end-start).count()/q.size()<<','<<check<<",0\n";
 std::vector<std::vector<std::uint32_t>> residues;residues.reserve(b.factors_.size());
 for(auto&f:b.factors_){residues.emplace_back(q.size());auto&v=residues.back();
  for(std::size_t j=0;j<q.size();++j){auto budget=b.options_.max_multiplicative_steps;v[j]=q[j].trivial?0:b.choose_factor(f,q[j].n,q[j].k,budget);}
  check=0;std::uint64_t nonzero=0;start=Clock::now();
  for(auto x:q){if(x.trivial)continue;auto budget=b.options_.max_multiplicative_steps;auto val=b.choose_factor(f,x.n,x.k,budget);check+=val;nonzero+=val!=0;}
  end=Clock::now();std::cout<<"factor,"<<f.modulus<<','<<std::chrono::duration<double,std::nano>(end-start).count()/q.size()<<','<<check<<','<<nonzero<<'\n';
 }
 check=0;std::uint64_t terms=0;start=Clock::now();
 for(std::size_t j=0;j<q.size();++j){std::uint64_t result=0;for(std::size_t i=0;i<b.factors_.size();++i){auto residue=residues[i][j];if(residue==0)continue;result+=static_cast<std::uint64_t>(residue)*b.factors_[i].crt_weight%b.modulus_;if(result>=b.modulus_)result-=b.modulus_;++terms;}check+=result;}
 end=Clock::now();std::cout<<"crt,0,"<<std::chrono::duration<double,std::nano>(end-start).count()/q.size()<<','<<check<<','<<terms<<'\n';
}

