from pathlib import Path
import subprocess,json,time,os,fcntl,statistics,hashlib,shutil,sys
p=Path(__file__).parent;label=sys.argv[1];specs=sys.argv[2:];dest=p/label;dest.mkdir(exist_ok=True)
sources={tag:str(Path(src).absolute()) for tag,src in (x.split('=',1) for x in specs)}
tags=['before',*sources,'control'];exes={'before':p/'before_fast'};metadata={}
for tag,src in sources.items():
 snapshot=dest/(tag+'_snapshot.cpp');shutil.copyfile(src,snapshot);driver=(p/'window_driver.cpp') if tag=='window' else (p/'fast_driver.cpp');out=dest/(tag+'.cpp');out.write_text(snapshot.read_text()+driver.read_text());subprocess.run(['g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',str(out),'-o',str(dest/tag)],check=True);exes[tag]=dest/tag;metadata[tag]={'source_sha256':hashlib.sha256(snapshot.read_bytes()).hexdigest(),'driver_sha256':hashlib.sha256(driver.read_bytes()).hexdigest()}
shutil.copyfile(p/'before_fast',dest/'control');os.chmod(dest/'control',0o755);exes['control']=dest/'control'
cases=sorted((p/'fixtures').glob('*.in'));checks=[]
for inp in cases:
 expected=p/'answers'/(inp.stem+'.out')
 for tag in sources:
  actual=dest/(tag+'_actual.out')
  with inp.open('rb')as si,actual.open('wb')as so:subprocess.run([str(exes[tag])],stdin=si,stdout=so,check=True)
  assert actual.read_bytes()==expected.read_bytes(),(tag,inp)
  subprocess.run([str(p/'bin/checker'),str(inp),str(actual),str(expected)],capture_output=True,check=True);checks.append({'case':inp.stem,'tag':tag,'pass':True})
(dest/'checker.json').write_text(json.dumps({'sources':metadata,'checks':checks},indent=2));print(label,'checker pass',len(checks),flush=True)
rows=[]
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX);os.sched_setaffinity(0,{14})
 for rep in range(5):
  for ci,inp in enumerate(cases):
   shift=(rep+ci)%len(tags)
   for tag in tags[shift:]+tags[:shift]:
    with inp.open('rb')as si:
     start=time.perf_counter_ns();subprocess.run([str(exes[tag])],stdin=si,stdout=subprocess.DEVNULL,check=True);dt=time.perf_counter_ns()-start
    rows.append({'case':inp.stem,'tag':tag,'rep':rep,'ns':dt})
  print(label,'rotation',rep+1,flush=True);(dest/'timings.json').write_text(json.dumps({'sources':metadata,'results':rows,'cpu':14,'reps':5},indent=2))
summary=[]
for inp in cases:
 row={'case':inp.stem}
 for tag in tags:row[tag]=statistics.median(x['ns']for x in rows if(x['case'],x['tag'])==(inp.stem,tag))/1e6
 summary.append(row)
(dest/'summary.json').write_text(json.dumps(summary,indent=2))
for row in summary:print(row['case'],*[f'{row[tag]:.3f}'for tag in tags])

