#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <new>
#include <vector>
#include <boost/multiprecision/cpp_int.hpp>
static std::int64_t fail_after=-1;
static std::uint64_t attempts=0,checks=0,failures=0;
static void* obtain(std::size_t n){if(fail_after>=0){++attempts;if(fail_after--==0)throw std::bad_alloc();}if(void*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void*operator new(std::size_t n){return obtain(n);}void*operator new[](std::size_t n){return obtain(n);}
void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
#include BINOMIAL_SOURCE
#define REQUIRE(x)do{++checks;if(!(x)){std::cerr<<"failed "<<__LINE__<<" "<<#x<<'\n';std::abort();}}while(false)
static std::uint32_t exact(std::uint32_t n,std::uint32_t k,std::uint32_t m){boost::multiprecision::cpp_int x=1;for(std::uint32_t i=1;i<=k;++i){x*=n-k+i;x/=i;}return static_cast<std::uint32_t>(x%m);}
int main(){
 for(std::uint32_t m:{8u,16u,27u,72u,360u,65536u,59049u,2357947691u,4294967295u,4294967291u})for(int mode=0;mode<2;++mode)for(int budget=0;budget<12;++budget){
  BinomialOptions o;o.table_limit=4096;o.max_multiplicative_steps=4096;BinomialMod b(m,0,o);b.prepare(3);const auto a=b.COM(5,2);const auto z=b.COM(5,1);const auto want=exact(127,31,m);bool threw=false;
  fail_after=budget;try{if(mode==0)REQUIRE(b.COM(127,31)==want);else b.prepare(257);}catch(const std::bad_alloc&){threw=true;++failures;}fail_after=-1;
  REQUIRE(b.COM(5,2)==a);REQUIRE(b.COM(5,1)==z);REQUIRE(b.COM(127,31)==want);b.prepare(257);REQUIRE(b.COM(127,31)==want);REQUIRE(b.COM(257,128)==exact(257,128,m));
  if(threw)REQUIRE(b.COM(63,29)==exact(63,29,m));
 }
 std::cout<<"{\"checks\":"<<checks<<",\"bad_alloc\":"<<failures<<",\"allocation_attempts\":"<<attempts<<"}\n";
}
